func (this *Derive) HandleOrderBookUnSubscription(client any, topic any) {
	var parsedTopic []string = ccxt.Split(topic, ".")
	var marketId *string = this.SafeString(parsedTopic, 1)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	if ccxt.InOp(this.Orderbooks, symbol) {
		ccxt.Remove(this.Orderbooks, symbol)
	}
	if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), topic) {
		ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), topic)
	}
	error := ccxt.UnsubscribeError(this.Id + " orderbook " + *symbol)
	client.(ccxt.ClientInterface).Reject(error, topic)
	client.(ccxt.ClientInterface).Resolve(error, ccxt.Add("unwatch", topic))
}
func (this *Derive) HandleTradesUnSubscription(client any, topic any) {
	var parsedTopic []string = ccxt.Split(topic, ".")
	var marketId *string = this.SafeString(parsedTopic, 1)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	if ccxt.InOp(this.Orderbooks, symbol) {
		ccxt.Remove(this.Trades, symbol)
	}
	if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), topic) {
		ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), topic)
	}
	error := ccxt.UnsubscribeError(this.Id + " trades " + *symbol)
	client.(ccxt.ClientInterface).Reject(error, topic)
	client.(ccxt.ClientInterface).Resolve(error, ccxt.Add("unwatch", topic))
}
func (this *Derive) HandleUnSubscribe(client any, message any) any {
	//
	// {
	//     id: 1,
	//     result: {
	//       status: { 'orderbook.BTC-PERP.10.10': 'ok' },
	//       remaining_subscriptions: []
	//     }
	// }
	//
	var result map[string]any = ccxt.SafeMapTyped(message, "result")
	var status map[string]any = ccxt.SafeMapTyped(result, "status")
	if !ccxt.IsEqual(status, nil) {
		var topics []string = ccxt.ObjectKeys(status)
		for i := 0; i < len(topics); i++ {
			var topic string = topics[i]
			if strings.Index(topic, "orderbook") >= 0 {
				this.HandleOrderBookUnSubscription(client, topic)
			} else if strings.Index(topic, "trades") >= 0 {
				this.HandleTradesUnSubscription(client, topic)
			}
		}
	}
	return message
}

