func (this *Derive) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	subaccountIdparamsDeriveSubaccountIdVariable := this.HandleDeriveSubaccountId("watchOrders", params)
	subaccountId := ccxt.GetValue(subaccountIdparamsDeriveSubaccountIdVariable, 0)
	var paramsDeriveSubaccountId map[string]any = ccxt.MapTyped(ccxt.GetValue(subaccountIdparamsDeriveSubaccountIdVariable, 1))
	var topic any = ccxt.Add(this.NumberToString(subaccountId), ".orders")
	var messageHash any = topic
	var symbolResolved any = func() any {
		if symbol != nil {
			return this.Symbol(symbol)
		}
		return symbol
	}()
	if !ccxt.IsEqual(symbolResolved, nil) {
		messageHash = ccxt.Add(messageHash, ccxt.Add(":", symbolResolved))
	}
	var request map[string]any = map[string]any{
		"method": "subscribe",
		"params": map[string]any{
			"channels": []any{topic},
		},
	}
	var subscription map[string]any = map[string]any{
		"name":   topic,
		"params": paramsDeriveSubaccountId,
	}
	var message map[string]any = this.Extend(request, paramsDeriveSubaccountId)

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.WatchPrivateAsync(messageHash, message, subscription))))
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(symbolResolved, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbolResolved, since, limitResolved, true)
	return nil
}
func (this *Derive) HandleOrder(client any, message map[string]any) {
	//
	// {
	//     method: 'subscription',
	//     params: {
	//         channel: '130837.orders',
	//         data: [
	//             {
	//                 subaccount_id: 130837,
	//                 order_id: '1f44c564-5658-4b69-b8c4-4019924207d5',
	//                 instrument_name: 'BTC-PERP',
	//                 direction: 'buy',
	//                 label: 'test1234',
	//                 quote_id: null,
	//                 creation_timestamp: 1738578974146,
	//                 last_update_timestamp: 1738578974146,
	//                 limit_price: '10000',
	//                 amount: '0.01',
	//                 filled_amount: '0',
	//                 average_price: '0',
	//                 order_fee: '0',
	//                 order_type: 'limit',
	//                 time_in_force: 'post_only',
	//                 order_status: 'untriggered',
	//                 max_fee: '219',
	//                 signature_expiry_sec: 1746354973,
	//                 nonce: 1738578973570,
	//                 signer: '0x30CB7B06AdD6749BbE146A6827502B8f2a79269A',
	//                 signature: '0xc6927095f74a0d3b1aeef8c0579d120056530479f806e9d2e6616df742a8934c69046361beae833b32b25c0145e318438d7d1624bb835add956f63aa37192f571c',
	//                 cancel_reason: '',
	//                 mmp: false,
	//                 is_transfer: false,
	//                 replaced_order_id: null,
	//                 trigger_type: 'stoploss',
	//                 trigger_price_type: 'mark',
	//                 trigger_price: '102800',
	//                 trigger_reject_message: null
	//             }
	//         ]
	//     }
	// }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var topic *string = this.SafeString(params, "channel")
	var rawOrders []any = ccxt.SafeListTyped(params, "data")
	for i := 0; i < len(rawOrders); i++ {
		var data any = func() any {
			if i >= 0 && i < len(rawOrders) {
				return ccxt.DerefScalar(rawOrders[i])
			}
			return nil
		}()
		var parsed map[string]any = ccxt.MapTyped(this.ParseOrder(data))
		var symbol *string = this.SafeString(parsed, "symbol")
		var orderId *string = this.SafeString(parsed, "id")
		if symbol != nil {
			if ccxt.IsEqual(this.Orders, nil) {
				var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
				this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
			}
			var cachedOrders any = this.Orders
			var orders map[string]any = ccxt.SafeMapTyped(cachedOrders.(*ccxt.ArrayCache).Hashmap, symbol)
			var order any = func() any {
				if orderId == nil {
					return nil
				}
				return this.SafeDict(orders, orderId)
			}()
			if !ccxt.IsEqual(order, nil) {
				var fee any = this.SafeValue(order, "fee")
				if !ccxt.IsEqual(fee, nil) {
					parsed["fee"] = fee
				}
				var fees any = this.SafeList(order, "fees")
				if !ccxt.IsEqual(fees, nil) {
					ccxt.AddElementToObject(parsed, "fees", fees)
				}
				parsed["trades"] = this.SafeValue(order, "trades")
				parsed["timestamp"] = this.SafeInteger(order, "timestamp")
				parsed["datetime"] = this.SafeString(order, "datetime")
			}
			cachedOrders.(ccxt.Appender).Append(parsed)
			if topic != nil {
				var messageHashSymbol string = *topic + ":" + *symbol
				client.(ccxt.ClientInterface).Resolve(this.Orders, messageHashSymbol)
			}
		}
	}
	client.(ccxt.ClientInterface).Resolve(this.Orders, topic)
}

