func (this *Derive) HandleMyTrade(client any, message map[string]any) {
	//
	//
	var myTrades any = this.MyTrades
	if ccxt.IsEqual(myTrades, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		myTrades = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var topic *string = this.SafeString(params, "channel")
	var rawTrades []any = ccxt.SafeListTyped(params, "data")
	for i := 0; i < len(rawTrades); i++ {
		var trade map[string]any = ccxt.MapTyped(this.ParseTrade(message))
		myTrades.(ccxt.Appender).Append(trade)
		client.(ccxt.ClientInterface).Resolve(myTrades, topic)
		if topic != nil {
			var messageHash string = *topic + *this.SafeString(trade, "symbol", "")
			client.(ccxt.ClientInterface).Resolve(myTrades, messageHash)
		}
	}
}
func (this *Derive) HandleErrorMessage(client any, message any) any {
	//
	// {
	//     id: '690c6276-0fc6-4121-aafa-f28bf5adedcb',
	//     error: { code: -32600, message: 'Invalid Request' }
	// }
	//
	if !(ccxt.InOp(message, "error")) {
		return false
	}
	var errorMessage map[string]any = ccxt.SafeMapTyped(message, "error")
	var errorCode *string = this.SafeString(errorMessage, "code")

	{
		ret__ := func(this *Derive) (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func(this *Derive) any {
						// catch block:
						if ccxt.IsInstance(error, ccxt.AuthenticationError) {
							var messageHash string = "authenticated"
							client.(ccxt.ClientInterface).Reject(error, messageHash)
							if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
								ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
							}
						} else {
							client.(ccxt.ClientInterface).Reject(error)
						}
						return true

					}(this)
				}
			}()
			// try block:
			if errorCode != nil {
				var feedback string = this.Id + " " + this.Json(message)
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
				panic(ccxt.ExchangeError(feedback))
			}
			return false

		}(this)
		if ret__ != nil {
			return ret__
		}
		return nil
	}
}
func (this *Derive) HandleMessage(client any, message any) {
	if ccxt.IsEqual(this.HandleErrorMessage(client, message), true) {
		return
	}
	var methods map[string]any = map[string]any{
		"orderbook":   this.HandleOrderBook,
		"ticker":      this.HandleTicker,
		"ticker_slim": this.HandleTicker,
		"trades":      this.HandleTrade,
		"orders":      this.HandleOrder,
		"mytrades":    this.HandleMyTrade,
	}
	var event *string = nil
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	if !ccxt.IsEqual(params, nil) {
		var channel *string = this.SafeString(params, "channel")
		if channel != nil {
			var parsedChannel []string = strings.Split(*channel, ".")
			if (func() int {
				if channel == nil {
					return -1
				}
				return strings.Index(*channel, "orders")
			}() >= 0) || (func() int {
				if channel == nil {
					return -1
				}
				return strings.Index(*channel, "trades")
			}() > 0) {
				event = this.SafeString(parsedChannel, 1)
				// {subaccounr_id}.trades
				if event != nil && *event == "trades" {
					event = ccxt.SafeStringPtr("mytrades")
				}
			} else {
				event = this.SafeString(parsedChannel, 0)
			}
		}
	}
	var method any = func() any {
		if event == nil {
			return nil
		}
		return this.SafeValue(methods, event)
	}()
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message)
		return
	}
	if ccxt.InOp(message, "id") {
		var id *string = this.SafeString(message, "id")
		var subscriptionsById map[string]any = this.IndexBy(client.(ccxt.ClientInterface).GetSubscriptions(), "id")
		var subscription any = func() any {
			if id == nil {
				return map[string]any{}
			}
			return this.SafeDict(subscriptionsById, id, map[string]any{})
		}()
		if ccxt.InOp(subscription, "method") {
			if this.SafeString(subscription, "method") != nil && *this.SafeString(subscription, "method") == "public/login" {
				this.HandleAuth(client, message)
			} else if this.SafeString(subscription, "method") != nil && *this.SafeString(subscription, "method") == "unsubscribe" {
				this.HandleUnSubscribe(client, message)
			}
		}
	}
}
func (this *Derive) HandleAuth(client any, message any) {
	//
	// {
	//     id: 1,
	//     result: [ 130837 ]
	// }
	//
	var messageHash string = "authenticated"
	var ids []any = ccxt.SafeListTyped(message, "result")
	if len(ids) > 0 {
		// client.resolve (message, messageHash)
		var future any = this.SafeValue(client.(ccxt.ClientInterface).GetFutures(), "authenticated")
		future.(*ccxt.Future).Resolve(true)
	} else {
		error := ccxt.AuthenticationError(this.Json(message))
		client.(ccxt.ClientInterface).Reject(error, messageHash)
		// allows further authentication attempts
		if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
			ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated")
		}
	}
}

func NewDerive(userConfig map[string]any) *Derive {
	p := newDerive()
	p.Init(userConfig)
	return p
}

func (this *Derive) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

